const rows = $input.all().map(i => i.json || {});
const config = $('Config').first().json;

const TZ = 'Asia/Bangkok';

function getBangkokParts(date = new Date()) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: TZ,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    weekday: 'short',
  }).formatToParts(date);
  const o = {};
  for (const p of parts) o[p.type] = p.value;
  return { year: +o.year, month: +o.month, day: +o.day, weekday: o.weekday };
}

function addDaysYMD(y, m, d, days) {
  const dt = new Date(Date.UTC(y, m - 1, d + days, 12, 0, 0));
  return {
    year: dt.getUTCFullYear(),
    month: dt.getUTCMonth() + 1,
    day: dt.getUTCDate(),
  };
}

function pad(n) { return String(n).padStart(2, '0'); }
function ymd(o) { return `${o.year}-${pad(o.month)}-${pad(o.day)}`; }
function dmy(o) { return `${pad(o.day)}/${pad(o.month)}/${o.year}`; }

function parseYMD(v) {
  if (v === null || v === undefined || String(v).trim() === '') return null;
  const s = String(v).trim();
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (m) return { year: +m[1], month: +m[2], day: +m[3] };
  m = s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/);
  if (m) return { year: +m[3], month: +m[2], day: +m[1] };
  return null;
}

function weekdayFromYMD(o) {
  const names = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  return names[new Date(Date.UTC(o.year, o.month - 1, o.day, 12, 0, 0)).getUTCDay()];
}

function normalizeDate(v) {
  if (v === null || v === undefined || v === '') return '';
  const s = String(v).trim();
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) return `${m[1]}-${pad(m[2])}-${pad(m[3])}`;
  m = s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/);
  if (m) return `${m[3]}-${pad(m[2])}-${pad(m[1])}`;
  const dt = new Date(s);
  if (!Number.isNaN(dt.getTime())) {
    return `${dt.getUTCFullYear()}-${pad(dt.getUTCMonth() + 1)}-${pad(dt.getUTCDate())}`;
  }
  return s;
}

function timeToMinutes(v) {
  if (v === null || v === undefined || v === '') return 99999;
  const s = String(v).trim();
  const m = s.match(/^(\d{1,2}):(\d{2})/);
  if (!m) return 99999;
  return (+m[1]) * 60 + (+m[2]);
}

function displayTime(v) {
  if (v === null || v === undefined || String(v).trim() === '') return '-';
  const s = String(v).trim();
  const m = s.match(/^(\d{1,2}):(\d{2})/);
  if (m) return `${pad(m[1])}:${m[2]}`;
  return s;
}

function clean(v) {
  if (v === null || v === undefined || String(v).trim() === '') return '-';
  return String(v).trim();
}

function parseNumber(v) {
  if (v === null || v === undefined || String(v).trim() === '') return 0;
  const n = Number(String(v).replace(/,/g, '').trim());
  return Number.isFinite(n) ? n : 0;
}

function formatQty(v) {
  const n = parseNumber(v);
  return new Intl.NumberFormat('en-US', { maximumFractionDigits: 2 }).format(n);
}

// รองรับ Trip Products Detail ได้ 2 รูปแบบ
// ใหม่: "ขวดมายช้อยส์ 500 = 12,087 ขวด = 79 แพ็ค (153 ขวด/แพ็ค)"
// เก่า:  "ขวดมายช้อยส์ 500 [12087]"
// หากชื่อสินค้าซ้ำในเที่ยวเดียวกัน จะรวมจำนวนขวดและจำนวนแพ็คให้
function getTripProducts(r) {
  const raw = String(r['Trip Products Detail'] ?? '').trim();
  const aggregated = new Map();

  function addProduct(name, qty, packs = null) {
    name = String(name || '').trim();
    if (!name) return;

    if (!aggregated.has(name)) {
      aggregated.set(name, { qty: 0, packs: null });
    }

    const current = aggregated.get(name);
    current.qty += Number.isFinite(qty) ? qty : 0;

    if (packs !== null && Number.isFinite(packs)) {
      current.packs = (current.packs ?? 0) + packs;
    }
  }

  if (raw) {
    const entries = raw
      .split('|')
      .map(s => s.trim())
      .filter(Boolean);

    for (const entry of entries) {
      // รูปแบบใหม่:
      // ชื่อสินค้า = 12,087 ขวด = 79 แพ็ค (...)
      let m = entry.match(/^(.*?)\s*=\s*([\d,.]+)\s*ขวด\s*=\s*([\d,.]+)\s*แพ็ค(?:\s*\([^)]*\))?\s*$/i);
      if (m) {
        addProduct(m[1], parseNumber(m[2]), parseNumber(m[3]));
        continue;
      }

      // Fallback รูปแบบเก่า:
      // ชื่อสินค้า [12087]
      m = entry.match(/^(.*?)\s*\[\s*([\d,.]+)\s*\]\s*$/);
      if (m) {
        addProduct(m[1], parseNumber(m[2]), null);
      }
    }
  }

  if (aggregated.size > 0) {
    return Array.from(aggregated.entries()).map(([name, value]) => ({
      name,
      qty: value.qty,
      packs: value.packs,
    }));
  }

  // Fallback สำหรับแถวเก่าที่ยังไม่มี Trip Products Detail
  // ถ้ามีสินค้าเดียว สามารถใช้ Trip Qty เป็นจำนวนสินค้าได้
  const productNames = String(r['Products'] ?? '')
    .split(',')
    .map(s => s.trim())
    .filter(Boolean);

  if (productNames.length === 1) {
    return [{
      name: productNames[0],
      qty: parseNumber(r['Trip Qty']),
      packs: null,
    }];
  }

  // มีหลายสินค้าแต่ไม่มีรายละเอียดรายสินค้า: ไม่เดาจำนวน
  return productNames.map(name => ({ name, qty: null, packs: null }));
}

function buildProductsLines(r) {
  const products = getTripProducts(r);
  if (products.length === 0) return ['ชื่อสินค้า: -'];

  const lines = ['ชื่อสินค้า:'];
  products.forEach((p, i) => {
    const qtyText = p.qty === null ? '-' : formatQty(p.qty);
    const packText = p.packs === null ? '' : ` (${formatQty(p.packs)} แพ็ค)`;
    lines.push(`${i + 1}. ${p.name} = ${qtyText}${packText}`);
  });
  lines.push(`รวมทั้งหมด: ${formatQty(r['Trip Qty'])}`);
  return lines;
}

// useTest = false -> use actual Bangkok date
// useTest = true  -> testDate is treated as the simulated "today" date.
// Example: testDate 2026-05-01 (Friday) -> report 2026-05-02 (Saturday)
//          testDate 2026-05-02 (Saturday) -> report 2026-05-04 (Monday)
const useTest = config.useTest === true || String(config.useTest).toLowerCase() === 'true';
let baseDate;

if (useTest) {
  baseDate = parseYMD(config.testDate);
  if (!baseDate) {
    throw new Error('Config.testDate ไม่ถูกต้อง กรุณาใช้รูปแบบ YYYY-MM-DD เช่น 2026-05-01 หรือ DD/MM/YYYY เช่น 01/05/2026');
  }
  baseDate.weekday = weekdayFromYMD(baseDate);
} else {
  baseDate = getBangkokParts();
}

const offset = baseDate.weekday === 'Sat' ? 2 : 1;
const report = addDaysYMD(baseDate.year, baseDate.month, baseDate.day, offset);
const reportDate = ymd(report);
const reportDateDisplay = dmy(report);
const baseDateText = ymd(baseDate);

const matched = rows
  .filter(r => normalizeDate(r['Shipping Date']) === reportDate)
  .filter(r => String(r['Plan Status'] ?? '').trim().toUpperCase() === 'SCHEDULED')
  .sort((a, b) => {
    const ta = timeToMinutes(a['Departure Time']);
    const tb = timeToMinutes(b['Departure Time']);
    if (ta !== tb) return ta - tb;
    return clean(a['Vehicle ID']).localeCompare(clean(b['Vehicle ID']), 'th');
  });

let message;

if (matched.length === 0) {
  message = `ไม่มีแผนจัดส่งสำหรับวันที่ ${reportDateDisplay}`;
} else {
  const parts = [
    '📦 รายงานแผนจัดส่ง',
    `วันที่ ${reportDateDisplay}`,
    ''
  ];

  matched.forEach((r, index) => {
    parts.push(`🚚 เที่ยวที่ ${index + 1}`);
    parts.push(`ทะเบียนรถ: ${clean(r['Vehicle ID'])}`);
    parts.push(`เวลาจัดส่ง: ${displayTime(r['Departure Time'])}`);
    parts.push(...buildProductsLines(r));
    parts.push(`ชื่อบริษัทลูกค้า: ${clean(r['Account Name'])}`);
    parts.push(`ชื่อคนขับรถ: ${clean(r['Driver Name'])}`);
    if (index < matched.length - 1) parts.push('');
  });

  message = parts.join('\n');
}

return [{
  json: {
    useTest,
    baseDate: baseDateText,
    reportDate,
    reportDateDisplay,
    matchedCount: matched.length,
    message
  }
}];
